payload.arguments:
{"command":"@'
{
  "skill_metadata": {
    "name": "Analyze Dota 2 hero Lua abilities and awaken modifiers",
    "description": "Scans a Dota 2 custom game hero script tree to summarize ability overrides, awaken modifiers, and gameplay logic changes, then emits a structured report suitable for docs or downstream automation.",
    "triggers": [
      "analyze hero lua scripts",
      "summarize ability changes",
      "generate awaken modifier report",
      "scan vscripts/hero for gameplay logic"
    ]
  },
  "io_spec": {
    "input": ["code_path", "user_intent"],
    "output": "result"
  },
  "execution_logic": "1) Discover files under code_path using a fast file walk (rg --files or equivalent). 2) Partition files by role: hero ability scripts (ability files), awaken modifiers (modifier_*_awaken.lua), and docs (ability analysis markdown). 3) Parse Lua files by lightweight pattern scanning (class/ability names, GetIntrinsicModifierName, OnAbilityFullyCast, OnTakeDamage, ApplyDamage, projectile creation, modifiers) to infer behavior changes and triggers. 4) Map user_intent to concrete actions (e.g., summary, list of modified abilities, detect disabled scripts) and select the minimum relevant file subset. 5) Emit result as structured JSON/Markdown with sections: file inventory, per-ability summary, modifier behaviors, and any disabled/empty scripts. Include concrete function or modifier identifiers when present for traceability.",
  "examples": [
    {
      "input": {
        "code_path": "game/awaken/scripts/vscripts/hero",
        "user_intent": "Summarize awaken modifiers and list heroes that have custom awaken behavior."
      },
      "output": {
        "result": {
          "summary": "Found awaken modifiers for many heroes; each modifier_*_awaken.lua encodes passive or reactive logic tied to difficulty and special items.",
          "heroes": [
            "abaddon",
            "alchemist",
            "axe",
            "crystal_maiden"
          ],
          "notes": "List is truncated in this example; full output would include all heroes with modifier_*_awaken.lua files."
        }
      }
    },
    {
      "input": {
        "code_path": "game/awaken/scripts/vscripts/hero",
        "user_intent": "Identify ability scripts that are empty or commented out."
      },
      "output": {
        "result": {
          "disabled_or_empty": [
            "hero/hero_axe/axe_culling_blade.lua",
            "hero/hero_lina/luna_eclipse.lua",
            "hero/hero_lion/lion_finger_of_death.lua"
          ],
          "notes": "This list is based on comment-only or zero-length files; verify against KV or other scripts for current behavior."
        }
      }
    }
  ]
}
'@ | Set-Content -Path "game/awaken/scripts/utils/skills/hero_skill.json" -Encoding ASCII
","workdir":"e:\DOTA"}

